<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {Search,RotateCcw,ReceiptText,Clock3,CircleCheck,Undo2,Eye,X,CheckCheck,Trash2,Copy,ShieldCheck} from 'lucide-vue-next'
import {request,send} from './api'
import {auditActionLabel} from '../../shared/audit'
import ProductDocument from './ProductDocument.vue'
const rows=ref<any[]>([]),total=ref(0),summary=ref<any>({}),busy=ref(false),error=ref(''),page=ref(1),pageSize=ref(20),testDeletion=ref(false)
const products=ref<any[]>([]),exams=ref<any[]>([]),cycles=ref<any[]>([])
const filters=reactive({search:'',productId:'',type:'',examId:'',cycleId:'',status:'',createdRange:[] as string[],paidRange:[] as string[]})
const statuses:Record<string,string>={pending_payment:'待支付',payment_failed:'支付失败',paid:'已支付',closed:'已关闭',refunding:'待线下退款',refunded:'已退款'}
const types:Record<string,string>={entitlement:'权益商品',trial:'体验权益'}
const statusColor=(s:string)=>s==='paid'?'success':s==='payment_failed'?'danger':['pending_payment','refunding'].includes(s)?'warning':'info'
const money=(c:any)=>'¥'+(Number(c||0)/100).toFixed(2)
const date=(s:any)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
const metrics=computed(()=>[
 {label:'今日订单',value:summary.value.today_orders||0,note:'今日成交 '+money(summary.value.today_paid_cents),icon:ReceiptText},
 {label:'待支付',value:summary.value.pending||0,note:'包含可重试的支付失败订单',icon:Clock3},
 {label:'已支付',value:summary.value.paid||0,note:'不含退款中及已退款订单',icon:CircleCheck},
 {label:'已退款金额',value:money(summary.value.refunded_cents),note:'工作人员已确认线下退款',icon:Undo2}
])
let revision=0
function query(){const p=new URLSearchParams({search:filters.search,productId:filters.productId,type:filters.type,examId:filters.examId,cycleId:filters.cycleId,status:filters.status,page:String(page.value),pageSize:String(pageSize.value)})
 for(const [prefix,range] of [['created',filters.createdRange],['paid',filters.paidRange]] as const)if(range?.length===2){p.set(prefix+'From',new Date(range[0]+'T00:00:00+08:00').toISOString());p.set(prefix+'To',new Date(range[1]+'T23:59:59.999+08:00').toISOString())}return p.toString()}
async function load(){const current=++revision;busy.value=true;error.value='';try{const data=await request('/admin/orders?'+query());if(current===revision){rows.value=data.items;total.value=data.total;summary.value=data.summary;testDeletion.value=data.testDeletionAllowed}}catch(e:any){if(current===revision)error.value=e.message}finally{if(current===revision)busy.value=false}}
async function options(){try{[products.value,exams.value,cycles.value]=await Promise.all([request('/admin/products'),request('/admin/exam-projects'),request('/admin/exams')])}catch(e:any){error.value=e.message}}
function search(){if(page.value!==1)page.value=1;else void load()}
function reset(){Object.assign(filters,{search:'',productId:'',type:'',examId:'',cycleId:'',status:'',createdRange:[],paidRange:[]});search()}
watch(()=>filters.examId,()=>filters.cycleId='');watch(page,load);watch(pageSize,search)
const drawer=ref(false),detail=ref<any>(),detailBusy=ref(false),detailError=ref(''),tab=ref('snapshot')
let detailRevision=0
async function open(row:any){const current=++detailRevision;drawer.value=true;detail.value=null;detailError.value='';detailBusy.value=true;tab.value='snapshot';try{const d=await request('/admin/orders/'+row.id);if(current===detailRevision)detail.value=d}catch(e:any){if(current===detailRevision)detailError.value=e.message}finally{if(current===detailRevision)detailBusy.value=false}}
const o=computed(()=>detail.value?.order),snap=computed(()=>o.value?.product_snapshot),fulfillment=computed(()=>o.value?.fulfillment_snapshot)
function fulfillmentState(row:any){if(!row?.paid_at)return '未发放';if(row.revoked)return '已撤销';if(new Date(row.entitlement_ends_at).getTime()<=Date.now())return '已到期';return '生效中'}
async function copy(value:string){try{await navigator.clipboard.writeText(value);ElMessage.success('订单号已复制')}catch{ElMessage.error('复制失败，请手动复制订单号')}}
const action=ref(''),actionRow=ref<any>(),actionOpen=ref(false),working=ref(false),actionError=ref(''),reason=ref(''),refundReference=ref(''),confirmation=ref('')
const actionTitles:Record<string,string>={closed:'关闭订单',refunding:'登记线下退款',refunded:'确认已线下退款',delete:'删除测试订单'}
function operate(row:any,next:string){action.value=next;actionRow.value=row;reason.value='';refundReference.value='';confirmation.value='';actionError.value='';actionOpen.value=true}
async function submit(){if(working.value)return;actionError.value='';if(reason.value.trim().length<3){actionError.value='请填写至少3个字的操作说明';return}if(action.value==='refunded'&&!refundReference.value.trim()){actionError.value='请填写线下退款凭证或转账流水号';return}if(action.value==='delete'&&confirmation.value!==actionRow.value.id){actionError.value='请输入完整订单号确认删除';return}
 working.value=true;try{if(action.value==='delete')await send('/admin/orders/'+actionRow.value.id,{reason:reason.value,confirmation:confirmation.value},'DELETE');else await send('/admin/orders/'+actionRow.value.id,{status:action.value,expectedStatus:actionRow.value.status,reason:reason.value,...(action.value==='refunded'?{refundReference:refundReference.value}:{})},'PATCH');actionOpen.value=false;ElMessage.success(action.value==='refunded'?'已记录线下退款并撤销对应权益':'操作已保存并记录日志');if(drawer.value&&o.value?.id===actionRow.value.id){if(action.value==='delete')drawer.value=false;else await open(actionRow.value)}await load();if(!rows.value.length&&page.value>1)page.value--}catch(e:any){actionError.value=e.message}finally{working.value=false}}
function beforeClose(done:()=>void){if(!working.value)done()}
onMounted(()=>{void load();void options()});defineExpose({load})
</script>

<template>
 <section class="orders-page">
  <div class="order-metrics"><article v-for="(m,i) in metrics" :key="m.label"><div class="metric-head"><span>{{m.label}}</span><component :is="m.icon" :size="20" :class="'order-metric-icon tone-'+i" aria-hidden="true"/></div><strong>{{m.value}}</strong><small>{{m.note}}</small></article></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <form class="admin-filters order-filters" @submit.prevent="search">
   <label class="admin-filter-field"><span>订单 / 用户</span><el-input v-model="filters.search" placeholder="订单号、手机号或昵称" clearable aria-label="订单或用户"><template #prefix><Search :size="16"/></template></el-input></label>
   <label class="admin-filter-field"><span>商品</span><el-select v-model="filters.productId" filterable :empty-values="[null,undefined]" aria-label="筛选商品"><el-option label="全部商品" value=""/><el-option v-for="p in products" :key="p.id" :label="p.title" :value="p.id"/></el-select></label>
   <label class="admin-filter-field"><span>商品类型</span><el-select v-model="filters.type" :empty-values="[null,undefined]" aria-label="筛选商品类型"><el-option label="全部类型" value=""/><el-option v-for="(name,key) in types" :key="key" :value="key" :label="name"/></el-select></label>
   <label class="admin-filter-field"><span>考试项目</span><el-select v-model="filters.examId" filterable :empty-values="[null,undefined]" aria-label="筛选考试"><el-option label="全部考试" value=""/><el-option v-for="e in exams" :key="e.id" :value="e.id" :label="e.name"/></el-select></label>
   <label class="admin-filter-field"><span>考期</span><el-select v-model="filters.cycleId" :disabled="!filters.examId" :empty-values="[null,undefined]" aria-label="筛选考期"><el-option label="全部考期" value=""/><el-option v-for="c in cycles.filter(c=>c.exam_id===filters.examId)" :key="c.id" :value="c.id" :label="c.year+' 年考期'"/></el-select></label>
   <label class="admin-filter-field"><span>订单状态</span><el-select v-model="filters.status" :empty-values="[null,undefined]" aria-label="筛选订单状态"><el-option label="全部状态" value=""/><el-option v-for="(name,key) in statuses" :key="key" :label="name" :value="key"/></el-select></label>
   <label class="admin-filter-field order-date-filter"><span>创建时间</span><el-date-picker v-model="filters.createdRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="创建日期范围"/></label>
   <label class="admin-filter-field order-date-filter"><span>支付时间</span><el-date-picker v-model="filters.paidRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="支付日期范围"/></label>
   <div class="admin-filter-actions"><el-button type="primary" native-type="submit" :loading="busy"><Search :size="16"/>查询</el-button><el-button @click="reset"><RotateCcw :size="16"/>重置</el-button></div>
  </form>
  <div class="table-toolbar"><span>订单列表 <b>{{total}}</b></span><small>统计随筛选条件变化 · 日期按北京时间</small></div>
  <el-table v-loading="busy" :data="rows" row-key="id" empty-text="暂无符合条件的订单">
   <el-table-column label="订单 / 商品" min-width="260"><template #default="{row}"><button class="table-title order-title" @click="open(row)">{{row.product_title}}</button><small class="order-number" :title="row.id">{{row.id}}</small><el-tag v-if="row.is_test_data" size="small" type="info" effect="plain">测试订单</el-tag></template></el-table-column>
   <el-table-column label="商品类型" width="110"><template #default="{row}">{{types[row.product_type]||row.product_type}}</template></el-table-column>
   <el-table-column label="用户" min-width="140"><template #default="{row}">{{row.nickname}}<small class="cell-sub">{{row.phone}}</small></template></el-table-column>
   <el-table-column prop="exam_name" label="考试项目" min-width="150"/>
   <el-table-column label="金额" width="120"><template #default="{row}"><strong class="order-amount">{{money(row.amount_cents)}}</strong><small class="cell-sub">{{row.paid_at?'实付金额':'待付金额'}}</small></template></el-table-column>
   <el-table-column label="订单状态" width="125"><template #default="{row}"><el-tag :type="statusColor(row.display_status)" effect="plain">{{statuses[row.display_status]}}</el-tag><small v-if="row.display_status==='payment_failed'" class="cell-sub">有效期内可重试</small></template></el-table-column>
   <el-table-column label="创建 / 支付时间" min-width="190"><template #default="{row}"><div class="order-times"><span>创建 {{date(row.created_at)}}</span><span>支付 {{date(row.paid_at)}}</span></div></template></el-table-column>
   <el-table-column label="权益到期时间" min-width="165"><template #default="{row}">{{row.paid_at?date(row.entitlement_ends_at):'—'}}<small v-if="row.paid_at" class="cell-sub">{{fulfillmentState(row)}}</small></template></el-table-column>
   <el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><div class="row-actions">
    <el-tooltip content="订单详情"><el-button link type="primary" aria-label="订单详情" @click="open(row)"><Eye :size="17"/></el-button></el-tooltip>
    <el-tooltip v-if="row.status==='pending_payment'" content="关闭订单"><el-button link type="warning" aria-label="关闭订单" @click="operate(row,'closed')"><X :size="17"/></el-button></el-tooltip>
    <el-tooltip v-if="row.status==='paid'" content="登记线下退款"><el-button link type="warning" aria-label="登记线下退款" @click="operate(row,'refunding')"><Undo2 :size="17"/></el-button></el-tooltip>
    <el-tooltip v-if="row.status==='refunding'" content="确认已线下退款"><el-button link type="success" aria-label="确认已线下退款" @click="operate(row,'refunded')"><CheckCheck :size="17"/></el-button></el-tooltip>
    <el-tooltip v-if="testDeletion&&row.is_test_data" content="删除测试订单"><el-button link type="danger" aria-label="删除测试订单" @click="operate(row,'delete')"><Trash2 :size="17"/></el-button></el-tooltip>
   </div></template></el-table-column>
  </el-table>
  <div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" :total="total" layout="sizes,prev,pager,next"/></div>
 </section>

 <el-drawer v-model="drawer" title="订单详情" size="min(960px,100vw)" class="order-drawer">
  <div v-loading="detailBusy"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><template v-if="o">
   <div class="order-detail-hero"><div><el-tag :type="statusColor(o.display_status)" effect="plain">{{statuses[o.display_status]}}</el-tag><h2>{{o.product_title}}</h2><button class="copy-order" @click="copy(o.id)" :aria-label="'复制订单号 '+o.id"><span>{{o.id}}</span><Copy :size="14"/></button></div><div class="hero-amount"><small>{{o.paid_at?'实付金额':'待付金额'}}</small><strong>{{money(o.amount_cents)}}</strong><span>{{o.is_test_data?'测试订单 · 未实际扣款':'正式订单'}}</span></div></div>
   <div class="order-party"><span>{{o.nickname}} · {{o.phone}}</span><span>{{o.exam_name}} · {{o.cycle_year}} 年考期 · {{o.entitlement_level.toUpperCase()}}</span></div>
   <el-tabs v-model="tab"><el-tab-pane label="商品快照" name="snapshot"/><el-tab-pane label="权益履约" name="fulfillment"/><el-tab-pane label="支付记录" name="payments"/><el-tab-pane label="处理记录" name="history"/></el-tabs>
   <section v-if="tab==='snapshot'" class="order-detail-section">
    <p class="detail-hint">以下为下单时的商品内容，后续修改商品不会改变此订单。</p>
    <el-descriptions :column="2" border><el-descriptions-item label="商品类型">{{types[o.product_type]}}</el-descriptions-item><el-descriptions-item label="商品版本">{{snap?.version?'V'+snap.version:'旧测试订单无版本'}}</el-descriptions-item><el-descriptions-item label="售价">{{money(o.amount_cents)}}</el-descriptions-item><el-descriptions-item label="划线原价">{{snap?.originalPriceCents?money(snap.originalPriceCents):'—'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{date(o.created_at)}}</el-descriptions-item><el-descriptions-item label="支付截止">{{date(o.expires_at)}}</el-descriptions-item><el-descriptions-item label="考期结束">{{date(snap?.endsAt)}}</el-descriptions-item><el-descriptions-item label="支付时间">{{date(o.paid_at)}}</el-descriptions-item></el-descriptions>
    <div v-if="snap" class="snapshot-content" :class="{'no-cover':!snap.coverUrl}"><img v-if="snap.coverUrl" :src="snap.coverUrl" alt="下单时的商品封面"/><div><p>{{snap.intro||'未填写商品简介'}}</p><h3>图文详情</h3><ProductDocument :document="snap.document"/></div></div><el-empty v-else description="旧测试订单未保存商品图文快照" :image-size="70"/>
   </section>
   <section v-if="tab==='fulfillment'" class="order-detail-section"><div class="fulfillment-banner"><ShieldCheck :size="24"/><div><strong>{{fulfillmentState(o)}}</strong><span>权益档位：{{o.entitlement_level.toUpperCase()}} · {{o.cycle_year}} 年考期</span></div></div>
    <el-descriptions :column="1" border><el-descriptions-item label="关联权益记录">{{o.entitlement_starts_at?'关联本订单（'+o.id+'）':'尚未发放'}}</el-descriptions-item><el-descriptions-item label="生效时间">{{date(o.entitlement_starts_at)}}</el-descriptions-item><el-descriptions-item label="到期时间">{{o.paid_at?date(o.entitlement_ends_at):'支付时确认'}}</el-descriptions-item><template v-if="o.product_type==='trial'"><el-descriptions-item label="配置体验时长">{{snap?.trialHours||24}} 小时</el-descriptions-item><el-descriptions-item label="实际生效时长">{{fulfillment?Math.floor(fulfillment.actualHours*100)/100+' 小时':o.entitlement_starts_at?Math.floor((new Date(o.entitlement_ends_at).getTime()-new Date(o.entitlement_starts_at).getTime())/36000)/100+' 小时':'尚未支付'}}</el-descriptions-item><el-descriptions-item label="临近考期缩短">{{fulfillment?(fulfillment.shortened?'是':'否'):'无确认记录'}}</el-descriptions-item><el-descriptions-item label="短时体验确认">{{fulfillment?.shortConfirmationAccepted?'用户已确认':fulfillment?'无需确认':'无确认记录'}}</el-descriptions-item><el-descriptions-item v-if="fulfillment?.shortened" label="当时提示模板">{{fulfillment.noticeTemplate}}</el-descriptions-item></template></el-descriptions>
    <p class="detail-hint">已发放权益按支付时记录的到期时间生效。确认退款或删除测试订单，只撤销本订单对应的权益。</p>
   </section>
   <section v-if="tab==='payments'" class="order-detail-section"><el-table :data="detail.payments" empty-text="暂无支付记录"><el-table-column label="支付流水" min-width="200"><template #default="{row}"><span class="payment-id">{{row.transaction_id||row.id}}</span><small v-if="row.merchant_reference" class="cell-sub">商户单号：{{row.merchant_reference}}</small></template></el-table-column><el-table-column label="渠道" min-width="120"><template #default="{row}">{{({wechat_test:'微信测试支付',wechat:'微信支付',alipay:'支付宝支付',alipay_sandbox:'支付宝沙箱'} as Record<string,string>)[row.method]||row.method}}</template></el-table-column><el-table-column label="结果" width="90"><template #default="{row}"><el-tag :type="row.status==='success'?'success':'danger'">{{row.status==='success'?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column label="时间" min-width="175"><template #default="{row}">{{date(row.created_at)}}</template></el-table-column><el-table-column prop="error" label="处理说明" min-width="130"/></el-table><p class="detail-hint">第三方支付显示服务商交易号。测试及沙箱流水不代表实际扣款。</p></section>
   <section v-if="tab==='history'" class="order-detail-section"><el-descriptions v-if="o.refund_requested_at||o.refunded_at" :column="1" border><el-descriptions-item label="退款登记">{{date(o.refund_requested_at)}}</el-descriptions-item><el-descriptions-item label="退款原因">{{o.refund_reason}}</el-descriptions-item><el-descriptions-item label="退款金额">{{money(o.amount_cents)}}（全额）</el-descriptions-item><el-descriptions-item label="确认退款时间">{{date(o.refunded_at)}}</el-descriptions-item><el-descriptions-item label="线下退款凭证">{{o.refund_reference||'待工作人员完成退款'}}</el-descriptions-item></el-descriptions><p v-if="o.close_reason" class="detail-hint">关闭原因：{{o.close_reason}}</p><el-timeline v-if="detail.history.length" class="order-timeline"><el-timeline-item v-for="h in detail.history" :key="h.id" :timestamp="date(h.created_at)" placement="top"><strong>{{auditActionLabel(h.action)}}</strong><p>{{h.details.reason}}</p><small>{{h.actor_name||'工作人员'}}{{h.details.refundReference?' · 凭证：'+h.details.refundReference:''}}</small></el-timeline-item></el-timeline><el-empty v-else description="暂无人工处理记录" :image-size="70"/></section>
  </template></div>
  <template #footer><el-button @click="drawer=false">关闭</el-button><template v-if="o"><el-button v-if="o.status==='pending_payment'" type="warning" @click="operate(o,'closed')">关闭订单</el-button><el-button v-if="o.status==='paid'" type="warning" @click="operate(o,'refunding')">登记线下退款</el-button><el-button v-if="o.status==='refunding'" type="primary" @click="operate(o,'refunded')">确认已线下退款</el-button></template></template>
 </el-drawer>

 <el-dialog v-model="actionOpen" :title="actionTitles[action]" width="min(520px,calc(100vw - 32px))" :close-on-click-modal="false" :before-close="beforeClose" class="order-action-dialog">
  <p class="action-product">{{actionRow?.product_title}} · {{money(actionRow?.amount_cents)}}</p>
  <el-alert :closable="false" show-icon :type="action==='delete'?'error':'warning'" :title="action==='refunded'?'仅在工作人员已完成线下退款后确认。此操作不会转账，将撤销本订单权益。':action==='refunding'?'登记后由工作人员联系用户并线下退款，当前权益暂时保留。':action==='delete'?'从订单列表移除并撤销本订单的测试权益。保留审计底稿及历史购买资格记录。':'关闭后用户不能继续支付此订单。'"/>
  <el-form label-position="top" :disabled="working"><el-form-item label="操作说明" required><el-input v-model="reason" type="textarea" :rows="3" maxlength="500" show-word-limit aria-label="操作说明" placeholder="填写联系情况、退款原因或删除原因"/></el-form-item><el-form-item v-if="action==='refunded'" label="线下退款凭证 / 转账流水号" required><el-input v-model="refundReference" maxlength="200" aria-label="线下退款凭证" placeholder="填写可核查的退款凭证编号"/></el-form-item><el-form-item v-if="action==='delete'" label="输入完整订单号确认删除" required><p class="confirm-order-id">{{actionRow?.id}}</p><el-input v-model="confirmation" aria-label="确认删除订单号"/></el-form-item></el-form>
  <el-alert v-if="actionError" :title="actionError" type="error" :closable="false"/>
  <template #footer><el-button :disabled="working" @click="actionOpen=false">取消</el-button><el-button :type="action==='delete'?'danger':'primary'" :loading="working" @click="submit">{{actionTitles[action]}}</el-button></template>
 </el-dialog>
